package com.hostelcare.controller;
import com.hostelcare.repository.*;import com.hostelcare.enums.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/reports") public class ReportController {private final ComplaintRepository complaints;private final CategoryRepository categories;private final FeedbackRepository feedback;private final UserRepository users;private final AssignmentRepository assignments;private final ComplaintHistoryRepository histories;public ReportController(ComplaintRepository c,CategoryRepository ca,FeedbackRepository f,UserRepository u,AssignmentRepository a,ComplaintHistoryRepository h){complaints=c;categories=ca;feedback=f;users=u;assignments=a;histories=h;}
 @GetMapping("/summary") public Map<String,Object> summary(){Map<String,Object> m=new LinkedHashMap<>();for(ComplaintStatus s:ComplaintStatus.values())m.put(s.name().toLowerCase(),complaints.countByStatus(s));m.put("total",complaints.count());m.put("feedbackCount",feedback.count());m.put("averageRating",feedback.averageRating()==null?0.0:feedback.averageRating());m.put("averageResolutionHours",histories.averageResolutionHours()==null?0.0:histories.averageResolutionHours());return m;}
 @GetMapping("/categories") public List<?> byCategory(){return categories.findAll().stream().map(c->Map.of("category",c.categoryName,"total",complaints.findAll().stream().filter(x->x.category.categoryId.equals(c.categoryId)).count())).toList();}
 @GetMapping("/hostels") public List<?> byHostel(){return complaints.findAll().stream().collect(java.util.stream.Collectors.groupingBy(c->c.room.hostel.hostelName,java.util.stream.Collectors.counting())).entrySet().stream().map(e->Map.of("hostel",e.getKey(),"total",e.getValue())).toList();}
 @GetMapping("/priority") public List<?> byPriority(){return java.util.Arrays.stream(Priority.values()).map(p->Map.of("priority",p.name(),"total",complaints.findAll().stream().filter(c->c.priority==p).count())).toList();}
 @GetMapping("/staff") public List<?> byStaff(){return users.findByRoleAndActiveTrue(Role.STAFF).stream().map(u->{long assigned=assignments.findByStaffUserIdAndActiveTrue(u.userId).size();long done=assignments.findByStaffUserIdAndActiveTrue(u.userId).stream().filter(a->a.complaint.status==ComplaintStatus.RESOLVED||a.complaint.status==ComplaintStatus.CLOSED).count();return Map.of("staff",u.name,"assigned",assigned,"completed",done);}).toList();}
 @GetMapping(value="/export",produces="text/csv") public ResponseEntity<String> export(){StringBuilder b=new StringBuilder("complaint_id,title,student,hostel,room,category,priority,status,created_at\n");for(var c:complaints.findAllByOrderByCreatedAtDesc()){b.append(c.complaintId).append(',').append(csv(c.title)).append(',').append(csv(c.student.name)).append(',').append(csv(c.room.hostel.hostelName)).append(',').append(csv(c.room.roomNumber)).append(',').append(csv(c.category.categoryName)).append(',').append(c.priority==null?"":c.priority).append(',').append(c.status).append(',').append(c.createdAt).append('\n');}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=hostelcare-report.csv").contentType(MediaType.parseMediaType("text/csv")).body(b.toString());}
 private String csv(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
}
